/**
 * Documents that ship with pre-built content.
 *
 * Each one has a seed file at public/seed/<docId>.yjs, generated by
 * `pnpm seed` (scripts/build-seeds.ts) and committed to the repo.
 */

export interface SeedBook {
  docId: string;
  gutenbergId: number;
}

export const SEED_BOOKS: SeedBook[] = [
  { docId: "the-yellow-wallpaper", gutenbergId: 1952 },
  { docId: "alice-in-wonderland", gutenbergId: 11 },
  { docId: "pride-and-prejudice", gutenbergId: 1342 },
];

/** Every document that has a seed file, including the welcome doc. */
export const SEEDED_DOC_IDS = new Set<string>([
  "getting-started",
  ...SEED_BOOKS.map((b) => b.docId),
]);

/**
 * The Yjs client ID every seed is written with. Fixing it means each seed
 * file is the same set of CRDT operations wherever it is applied (browser,
 * server, a second browser), so applying it more than once changes nothing.
 * Real clients get random 32-bit IDs, so a collision with 1 is not a concern.
 */
export const SEED_CLIENT_ID = 1;
